const _enc=new TextEncoder();
const JWT_SECRET = 'cosmisk-jwt-secret-2026-v1';
const authHeader = $input.first().json.headers?.authorization || '';
if (!authHeader.startsWith('Bearer ')) {
  return [{ json: { _unauthorized: true } }];
}
const token = authHeader.replace('Bearer ', '');
try {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('invalid');
  const sig = b64url(hmacSHA256(_enc.encode(JWT_SECRET), _enc.encode(parts[0] + '.' + parts[1])));
  if (sig !== parts[2]) throw new Error('bad sig');
  const decoded = JSON.parse(Buffer.from(parts[1], 'base64url').toString());
  if (decoded.exp && Math.floor(Date.now() / 1000) > decoded.exp) {
    return [{ json: { _unauthorized: true } }];
  }
  return [{ json: { ...$input.first().json, _user: decoded } }];
} catch(e) {
  return [{ json: { _unauthorized: true } }];
}

const body = $input.first().json.body || $input.first().json;
const project_id = (body.project_id || '').trim();

if (!project_id) {
  return [{ json: { _error: true, message: 'project_id is required' } }];
}

return [{ json: { project_id, _user: $input.first().json._user } }];

const project = $input.first().json;
const clientCode = project.fields?.client_code || '';

// Store project data and client_code for next nodes
return [{ json: { project, client_code: clientCode } }];

// Gather data (sequential: Extract Client Code → Fetch Concepts → Fetch Scripts → here)
const projectData = $('Extract Client Code').first().json.project;
const conceptsData = $('Fetch Concepts').first().json;
const scriptsData = $input.first().json;

const conceptRecords = (conceptsData.records || []);
const scriptRecords = (scriptsData.records || []);

// Transform project
const project = {
  id: projectData.id,
  client_code: projectData.fields?.client_code || '',
  brand_name: projectData.fields?.brand_name || '',
  status: projectData.fields?.status || projectData.fields?.Status || '',
  num_scripts: projectData.fields?.num_scripts || 0,
  created_at: projectData.fields?.created_at || projectData.createdTime || '',
  pm_email: projectData.fields?.pm_email || '',
  client_name: projectData.fields?.client_name || '',
  client_email: projectData.fields?.client_email || '',
  website_url: projectData.fields?.website_url || '',
  brand_personality: projectData.fields?.brand_personality || '',
  target_user: projectData.fields?.target_user || '',
  target_audience: projectData.fields?.target_user || '',
  product_feature: projectData.fields?.product_feature || '',
  differentiator: projectData.fields?.differentiator || ''
};

// Transform concepts
const concepts = conceptRecords.map(c => ({
  id: c.id,
  concept_name: c.fields?.concept_name || c.fields?.name || '',
  title: c.fields?.concept_name || c.fields?.name || '',
  status: c.fields?.status || c.fields?.Status || '',
